    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef _list_build(vals):\n    head = cur = ListNode()\n    for v in vals:\n        cur.next = ListNode(v)\n        cur = cur.next\n    return head.next\n\ndef _list_show(head):\n    out = []\n    while head:\n        out.append(head.val)\n        head = head.next\n    return out\n\ndef _list_array_build(arr):\n    return [_list_build(x) for x in arr]\n\ndef _list_array_show(arr):\n    return [_list_show(x) for x in arr]\n\nclass Solution:\n    def pairSum(self, head: Optional[ListNode]) -> int:\n        slow, fast = head, head.next\n        while fast.next:\n            slow = slow.next\n            fast = fast.next.next\n\n        # \u53cd\u8f6c\u94fe\u8868\n        last = slow.next\n        while last.next:\n            cur = last.next\n            last.next = cur.next\n            cur.next = slow.next\n            slow.next = cur\n\n        ans = 0\n        x, y = head, slow.next\n        while y:\n            ans = max(ans, x.val + y.val)\n            x, y = x.next, y.next\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _list_build(_args[0])\n    _ret = _sol.pairSum(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
