    "medium",
    "\u53cc\u6307\u9488/\u6ed1\u52a8\u7a97\u53e3",
    "\u7ed9\u4f60\u4e00\u4e2a\u4e0b\u6807\u4ece 0\u00a0\u5f00\u59cb\u7684\u6574\u6570\u6570\u7ec4\u00a0players\u00a0\uff0c\u5176\u4e2d\u00a0players[i]\u00a0\u8868\u793a\u7b2c i\u00a0\u540d\u8fd0\u52a8\u5458\u7684 \u80fd\u529b\u00a0\u503c\uff0c\u540c\u65f6\u7ed9\u4f60\u4e00\u4e2a\u4e0b\u6807\u4ece 0\u00a0\u5f00\u59cb\u7684\u6574\u6570\u6570\u7ec4\u00a0trainers\u00a0\uff0c\u5176\u4e2d\u00a0trainers[j]\u00a0\u8868\u793a\u7b2c j\u00a0\u540d\u8bad\u7ec3\u5e08\u7684 \u8bad\u7ec3\u80fd\u529b\u503c\u00a0\u3002\n\n\u5982\u679c\u7b2c i\u00a0\u540d\u8fd0\u52a8\u5458\u7684\u80fd\u529b\u503c \u5c0f\u4e8e\u7b49\u4e8e\u00a0\u7b2c j\u00a0\u540d\u8bad\u7ec3\u5e08\u7684\u80fd\u529b\u503c\uff0c\u90a3\u4e48\u7b2c\u00a0i\u00a0\u540d\u8fd0\u52a8\u5458\u53ef\u4ee5 \u5339\u914d\u00a0\u7b2c\u00a0j\u00a0\u540d\u8bad\u7ec3\u5e08\u3002\u9664\u6b64\u4ee5\u5916\uff0c\u6bcf\u540d\u8fd0\u52a8\u5458\u81f3\u591a\u53ef\u4ee5\u5339\u914d\u4e00\u4f4d\u8bad\u7ec3\u5e08\uff0c\u6bcf\u4f4d\u8bad\u7ec3\u5e08\u6700\u591a\u53ef\u4ee5\u5339\u914d\u4e00\u4f4d\u8fd0\u52a8\u5458\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u6ee1\u8db3\u4e0a\u8ff0\u8981\u6c42\u00a0players\u00a0\u548c trainers\u00a0\u7684 \u6700\u5927 \u5339\u914d\u6570\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1aplayers = [4,7,9], trainers = [8,2,5,8]\n\u8f93\u51fa\uff1a2\n\u89e3\u91ca\uff1a\n\u5f97\u5230\u4e24\u4e2a\u5339\u914d\u7684\u4e00\u79cd\u65b9\u6848\u662f\uff1a\n- players[0] \u4e0e trainers[0] \u5339\u914d\uff0c\u56e0\u4e3a 4 \u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1aplayers = [1,1,1], trainers = [10]\n\u8f93\u51fa\uff1a1\n\u89e3\u91ca\uff1a\n\u8bad\u7ec3\u5e08\u53ef\u4ee5\u5339\u914d\u6240\u6709 3 \u4e2a\u8fd0\u52a8\u5458\n\u6bcf\u4e2a\u8fd0\u52a8\u5458\u81f3\u591a\u53ea\u80fd\u5339\u914d\u4e00\u4e2a\u8bad\u7ec3\u5e08\uff0c\u6240\u4ee5\u6700\u5927\u7b54\u6848\u662f 1 \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= players.length, trainers.length <= 105\n\n\t1 <= players[i], trainers[j] <= 109",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1aplayers\u3001trainers\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def matchPlayersAndTrainers(self, players: List[int], trainers: List[int]) -> int:\n        players.sort()\n        trainers.sort()\n        m, n = len(players), len(trainers)\n        i = j = count = 0\n\n        while i < m and j < n:\n            while j < n and players[i] > trainers[j]:\n                j += 1\n            if j < n:\n                count += 1\n            i += 1\n            j += 1\n        \n        return count\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.matchPlayersAndTrainers(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
