PPM15 = mk(
    "PM15",
    "\u5206\u9694\u94fe\u8868",
    "LeetCode 86",
    "medium",
    "\u53cc\u6307\u9488/\u6ed1\u52a8\u7a97\u53e3",
    "\u7ed9\u4f60\u4e00\u4e2a\u94fe\u8868\u7684\u5934\u8282\u70b9 head \u548c\u4e00\u4e2a\u7279\u5b9a\u503c x \uff0c\u8bf7\u4f60\u5bf9\u94fe\u8868\u8fdb\u884c\u5206\u9694\uff0c\u4f7f\u5f97\u6240\u6709 \u5c0f\u4e8e x \u7684\u8282\u70b9\u90fd\u51fa\u73b0\u5728 \u5927\u4e8e\u6216\u7b49\u4e8e x \u7684\u8282\u70b9\u4e4b\u524d\u3002\n\n\u4f60\u5e94\u5f53 \u4fdd\u7559 \u4e24\u4e2a\u5206\u533a\u4e2d\u6bcf\u4e2a\u8282\u70b9\u7684\u521d\u59cb\u76f8\u5bf9\u4f4d\u7f6e\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1ahead = [1,4,3,2,5,2], x = 3\n\u8f93\u51fa\uff1a[1,2,2,4,3,5]\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1ahead = [2,1], x = 2\n\u8f93\u51fa\uff1a[1,2]\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t\u94fe\u8868\u4e2d\u8282\u70b9\u7684\u6570\u76ee\u5728\u8303\u56f4 [0, 200] \u5185\n\n\t-100\n\n\t-200",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1ahead\u3001x\u3002",
    "\u8f93\u51fa ListNode \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef _list_build(vals):\n    head = cur = ListNode()\n    for v in vals:\n        cur.next = ListNode(v)\n        cur = cur.next\n    return head.next\n\ndef _list_show(head):\n    out = []\n    while head:\n        out.append(head.val)\n        head = head.next\n    return out\n\ndef _list_array_build(arr):\n    return [_list_build(x) for x in arr]\n\ndef _list_array_show(arr):\n    return [_list_show(x) for x in arr]\n\nclass Solution:\n    def partition(self, head: Optional[ListNode], x: int) -> Optional[ListNode]:\n        sml_dummy, big_dummy = ListNode(0), ListNode(0)\n        sml, big = sml_dummy, big_dummy\n        while head:\n            if head.val < x:\n                sml.next = head\n                sml = sml.next\n            else:\n                big.next = head\n                big = big.next\n            head = head.next\n        sml.next = big_dummy.next\n        big.next = None\n        return sml_dummy.next\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n    _args[0] = _list_build(_args[0])\n    _ret = _sol.partition(_args[0], _args[1])\n    _out = json.dumps(_list_show(_ret), separators=(',', ':'))\n    sys.stdout.write(_out)\n\nmain()\n",
    "token_list",
    [["[1,4,3,2,5,2]\n3", "[1,2,2,4,3,5]"], ["[2,1]\n2", "[1,2]"]],
    ["linked-list", "two-pointers", "\u53cc\u6307\u9488/\u6ed1\u52a8\u7a97\u53e3"],
    )
